SELECT CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, MIN(i.quantity) AS min_quantity FROM inventory i FULL OUTER JOIN products p ON p.id = i.product_id WHERE SIZE(p.tags) > 2 GROUP BY CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY min_quantity DESC, launch_cohort DESC LIMIT 50
